contentRule.content:
@js:
var html=result,
header={"Referer":baseUrl};
(function getImgList(){
    var p = "z_img=\'\\[(.*?)\\]";
    var path = html.match(p)[1].replace(/\"/g, "").replace(/\\/g, "").split(",");
    var piclist = new Array([path.length]);
    for (var i = 0; i < path.length; i++) {
        piclist[i] = "https://img.xpelly.com/"+ path[i];
    }
    return piclist;
}()).map(uri=>
'<img src="'+uri+'">').join("\n")

