source.exploreUrl:
@js:
var result = [];
var push = (title, url, size) => result.push({"title": title,"url": url,"style": {"layout_flexGrow": 1,"layout_flexBasisPercent": size}});
var sourceUrl=getHost();
var tagUrl = sourceUrl+"/rank.html";
var tag = java.ajax(tagUrl);

var tagList = org.jsoup.Jsoup.parse(tag).select(".menu .rank:nth-child(2) a");
var tagList1 = org.jsoup.Jsoup.parse(tag).select(".menu .rank:nth-child(1) a");
var tagSize = 0.4;

var prefix = sourceUrl;

push("男频",null,1);
for (var i in tagList) {
    var title = tagList[i].text();
    var url = prefix + `rank_1_0_{{page}}.html`;
    if(i > 0){
        url = prefix + String(tagList[i].attr("href")).replace(/(.*_)\d+(.html)$/, `$1{{page}}$2`);
    }
    title = String(title).replace(/\s/g, "");
    push(title, url, tagSize);
}
var spaceLength = tagList.length % 2;
for (i = 0; i < spaceLength; i++) {
     push("——",null,tagSize);
}

push("女频",null,1);
for (var i in tagList1) {
    var title = tagList1[i].text();
    var url = prefix + String(tagList1[i].attr("href")).replace(/(.*_)\d+(.html)$/, `$1{{page}}$2`);
    title = String(title).replace(/\s/g, "");
    push(title, url, tagSize);
}
var spaceLength1 = tagList1.length % 2;
for (i = 0; i < spaceLength1; i++) {
     push("——",null,tagSize);
}
JSON.stringify(result);

